def test_nested_configuration_isolation():
    base = {"network": {"retries": 3}}
    over = {"network": {"timeout": 5}}
    merged = merge_tenant_routing(base, over)
    # This modification to `merged` should not affect `base`
    merged["network"]["retries"] = 99
    assert base["network"]["retries"] == 3
    assert merged["network"]["retries"] == 99

def test_deep_merge_and_isolation():
    base = {"network": {"retries": 3, "timeout": 30}, "db": {"port": 5432}}
    over = {"network": {"timeout": 5, "protocol": "TCP"}, "db": {"host": "localhost"}}

    merged = merge_tenant_routing(base, over)

    expected_merged = {
        "network": {"retries": 3, "timeout": 5, "protocol": "TCP"},
        "db": {"port": 5432, "host": "localhost"}
    }
    assert merged == expected_merged

    # Ensure immutability of original base config
    assert base == {"network": {"retries": 3, "timeout": 30}, "db": {"port": 5432}}

    # Ensure deep copy: modifying merged should not affect base
    merged["network"]["retries"] = 999
    assert base["network"]["retries"] == 3
    assert merged["network"]["retries"] == 999

    # Ensure deep copy: modifying merged should not affect overrides
    over_copy = copy.deepcopy(over) # Make a copy to check against later
    merged["db"]["host"] = "remotehost"
    assert over_copy["db"]["host"] == "localhost"
    assert merged["db"]["host"] == "remotehost"

